import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}

/* --- HELPER COMPONENTS --- */

// Minimal logic to generate calendar days for accuracy
const getDaysInMonth = (year: number, month: number) => {
  return new Date(year, month + 1, 0).getDate();
};
const getStartDay = (year: number, month: number) => {
  return new Date(year, month, 1).getDay();
};

const MONTH_NAMES = [
  "JAN", "FEB", "MAR", "APR", "MAY", "JUN",
  "JUL", "AUG", "SEP", "OCT", "NOV", "DEC"
];

const MiniMonth: React.FC<{
  year: number;
  monthIndex: number;
  textColor: string;
  accentColor: string;
}> = ({ year, monthIndex, textColor, accentColor }) => {
  const daysInMonth = getDaysInMonth(year, monthIndex);
  const startDay = getStartDay(year, monthIndex); // 0 = Sun
  
  const days = Array.from({ length: daysInMonth }, (_, i) => i + 1);
  const blanks = Array.from({ length: startDay }, (_, i) => i);

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 4, opacity: 0.9 }}>
      <div style={{ 
        fontSize: 14, 
        fontWeight: 700, 
        color: accentColor,
        marginBottom: 2,
        letterSpacing: "0.05em"
      }}>
        {MONTH_NAMES[monthIndex]}
      </div>
      <div style={{ 
        display: "grid", 
        gridTemplateColumns: "repeat(7, 1fr)", 
        gap: 2,
        fontSize: 8,
        color: textColor,
        fontFamily: "Inter" 
      }}>
        {blanks.map((b) => <div key={`blank-${b}`} />)}
        {days.map((d) => (
          <div key={d} style={{ textAlign: "center", opacity: 0.7 }}>
            {d}
          </div>
        ))}
      </div>
    </div>
  );
};

const YearGrid: React.FC<{
  year: string;
  label: string;
  width: number;
  textColor: string;
  accentColor: string;
}> = ({ year, label, width, textColor, accentColor }) => {
  const numericYear = parseInt(year);
  
  return (
    <div style={{
      width: width,
      height: "100%",
      display: "flex",
      flexDirection: "column",
      alignItems: "center",
      justifyContent: "center",
      padding: 60,
      position: "relative"
    }}>
      {/* Huge Background Year Number */}
      <div style={{
        position: "absolute",
        top: "50%",
        left: "50%",
        transform: "translate(-50%, -50%)",
        fontSize: width * 0.35,
        fontWeight: 700,
        color: textColor,
        opacity: 0.05,
        fontFamily: "Oswald",
        whiteSpace: "nowrap",
        zIndex: 0,
      }}>
        {label}
      </div>

      <h1 style={{
        fontSize: 80,
        fontFamily: "Oswald",
        color: textColor,
        marginBottom: 40,
        zIndex: 1,
        position: "relative"
      }}>
        {label}
      </h1>

      <div style={{
        display: "grid",
        gridTemplateColumns: "repeat(4, 1fr)",
        gap: 30,
        width: "100%",
        zIndex: 1,
        position: "relative"
      }}>
        {Array.from({ length: 12 }).map((_, i) => (
          <MiniMonth 
            key={i} 
            year={numericYear} 
            monthIndex={i} 
            textColor={textColor}
            accentColor={accentColor}
          />
        ))}
      </div>
    </div>
  );
};

/* --- MAIN COMPONENT --- */



export type CalendarZoomProps = Record<string, any>;

const CalendarZoom: React.FC<CalendarZoomProps> = ({
  backgroundColor = "#111111",
  transparentBackground = false,
  durationInSeconds = 8,
  year1Text = "2024",
  year2Text = "2025",
  primaryTextColor = "#ffffff",
  accentColor = "#3b82f6",
}) => {
  useFontLoader(["Inter", "Oswald"]);
  
  const frame = useCurrentFrame();
  const { width, fps, durationInFrames } = useVideoConfig();

  // Handle transparency
  const bg = transparentBackground ? "transparent" : backgroundColor;
  
  // Animation Parameters
  const moveProgress = interpolate(
    frame,
    [0, durationInFrames - 15],
    [0, 1],
    {
      easing: Easing.bezier(0.25, 0.1, 0.25, 1),
      extrapolateRight: "clamp",
    }
  );

  // 1. Layout Math
  // We place two years side-by-side. 
  // Total container width is roughly 2.2x screen width to allow gaps.
  const containerWidth = width * 2.2;
  const singleYearWidth = width * 0.9; // Each year takes up 90% of a screen width
  const gap = width * 0.2; // Gap between years

  // 2. Camera Movement (Translate X)
  // Start: Centered on Year 1
  // Target: Centered on Year 2
  // Center of Year 1 relative to container start = singleYearWidth / 2
  // Center of Year 2 relative to container start = singleYearWidth + gap + (singleYearWidth / 2)
  // To center Year 1 in viewport (width/2): translateX = (width/2) - (singleYearWidth/2)
  // To center Year 2: translateX = (width/2) - (singleYearWidth + gap + singleYearWidth/2)
  
  const startX = (width / 2) - (singleYearWidth / 2);
  const endX = (width / 2) - (singleYearWidth + gap + (singleYearWidth / 2));

  const translateX = interpolate(moveProgress, [0, 1], [startX, endX]);

  // 3. Zoom Effect (Scale)
  // Slight zoom out first to see 2024, then zoom in "through" towards 2025
  const scale = interpolate(
    frame,
    [0, durationInFrames * 0.3, durationInFrames],
    [1, 0.9, 1.4], // Subtle zoom out then strong push in
    { easing: Easing.inOut(Easing.quad) }
  );
  
  // 4. Slight Rotation for dynamic feel
  const rotateY = interpolate(
    frame,
    [0, durationInFrames],
    [5, -5], // Slight perspective shift from looking left to looking right
    { extrapolateRight: "clamp" }
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bg }}>
      <div
        style={{
          width: "100%",
          height: "100%",
          perspective: "1000px", // Enable 3D perspective
          overflow: "hidden",
        }}
      >
        <div
          style={{
            display: "flex",
            flexDirection: "row",
            alignItems: "center",
            width: containerWidth,
            height: "100%",
            transform: `translateX(${translateX}px) scale(${scale}) rotateY(${rotateY}deg)`,
            transformStyle: "preserve-3d",
            transformOrigin: "center center",
            willChange: "transform",
            // Use transition: none to ensure Remotion controls everything
            transition: "none", 
          }}
        >
          {/* Year 1 Container */}
          <div style={{ width: singleYearWidth, height: "100%" }}>
            <YearGrid 
              year={year1Text}
              label={year1Text}
              width={singleYearWidth}
              textColor={primaryTextColor}
              accentColor={accentColor}
            />
          </div>

          {/* Gap */}
          <div style={{ width: gap }} />

          {/* Year 2 Container */}
          <div style={{ width: singleYearWidth, height: "100%" }}>
            <YearGrid 
              year={year2Text}
              label={year2Text}
              width={singleYearWidth}
              textColor={primaryTextColor}
              accentColor={accentColor}
            />
          </div>
        </div>
      </div>
      
      {/* Optional Overlay / Vignette for focus */}
      <AbsoluteFill
        style={{
          background: `radial-gradient(circle at center, transparent 40%, ${backgroundColor}E6 100%)`,
          pointerEvents: "none",
        }}
      />
    </AbsoluteFill>
  );
};

export default CalendarZoom;